<script setup>
import {ref,onUnmounted} from 'vue';import BaseModal from '../components/BaseModal.vue';import AccessMatrix from '../components/AccessMatrix.vue';import {state,api,useResource,changed,notify,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';
const show=ref(false),form=ref({}),error=ref(''),busy=ref(false);let baseline='';const {data,error:loadError}=useResource(async()=>{const [groups,users,catalog]=await Promise.all([api('/groups'),api('/users'),api('/permissions/catalog')]);return {groups,users,catalog};},{groups:[],users:[],catalog:null});
function open(g=null){form.value=g?JSON.parse(JSON.stringify(g)):{name:'',description:'',active:true,company_ids:[],user_ids:[],permissions:[]};baseline=JSON.stringify(form.value);error.value='';show.value=true;state.editor={name:'Grupo de usuários'};}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar alterações?',message:'O grupo ainda não foi salvo.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{const payload={...form.value,permissions:form.value.permissions.filter(p=>form.value.company_ids.includes(p.company_id))};await api('/groups'+(form.value.id?'/'+form.value.id:''),{method:form.value.id?'PUT':'POST',body:payload});show.value=false;state.editor=null;changed();notify('Grupo salvo. Os integrantes deverão entrar novamente.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">SISTEMA · CONTROLE DE ACESSO</div><h1>Grupos de usuários</h1><p>Conceda empresas, módulos, rotinas e ações para uma equipe.</p></div><button class="button primary" @click="open()">Novo grupo</button></header><p v-if="loadError" class="message error">{{loadError}}</p><section class="panel table-scroll"><table><thead><tr><th>Grupo</th><th>Situação</th><th>Empresas</th><th>Integrantes</th><th></th></tr></thead><tbody><tr v-for="g in data.groups" :key="g.id"><td><strong>{{g.name}}</strong><small class="cell-secondary">{{g.description}}</small></td><td>{{g.active?'Ativo':'Desativado'}}</td><td>{{g.company_ids.length}}</td><td>{{g.user_ids.length}}</td><td><button class="button small" @click="open(g)">Editar grupo</button></td></tr><tr v-if="!data.groups.length"><td colspan="5">Crie um grupo para reunir os acessos da equipe.</td></tr></tbody></table></section><BaseModal v-if="show" title="Grupo de usuários" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="group-form" @submit.prevent="save"><div class="form-grid"><label>Nome *<input v-model="form.name" required maxlength="100"/></label><label>Situação<select v-model="form.active"><option :value="true">Ativo</option><option :value="false">Desativado</option></select></label><label class="span-2">Descrição<input v-model="form.description" maxlength="500"/></label></div><fieldset><legend>Empresas acessíveis</legend><label v-for="c in state.companies" :key="c.id" class="inline-choice"><input v-model="form.company_ids" type="checkbox" :value="c.id"/>{{c.code}} · {{c.name}}</label><small>Ao remover uma empresa, suas permissões neste grupo também são removidas ao salvar.</small></fieldset><fieldset><legend>Integrantes</legend><label v-for="u in data.users" :key="u.id" class="inline-choice"><input v-model="form.user_ids" type="checkbox" :value="u.id"/>{{u.username}} {{u.active?'':'(desativado)'}}</label></fieldset><AccessMatrix v-if="data.catalog" v-model="form.permissions" :catalog="data.catalog" :company-ids="form.company_ids"/></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="group-form" :disabled="busy">Salvar grupo</button></template></BaseModal></div></template>
